\documentclass[11pt]{article}
\usepackage{amsmath,amssymb}

\title{A Stabilised Finite Element Discretisation for Full-Waveform Inversion in Viscoacoustic Media}
\author{T.~Banda and I.~Sorensen}
\date{April 2026}

\begin{document}
\maketitle

\begin{abstract}
We present a stabilised finite element solver for viscoacoustic
full-waveform inversion. The formulation remains stable under
aggressive mesh coarsening, and synthetic tests on a salt-flank
model show wavelength-scale recovery of the wavespeed field.
\end{abstract}

