\section*{Notation}
\begin{center}
\begin{tabular}{ll}
$v(x,z)$ & wavespeed (m/s) \\
$p(x,z,t)$ & pressure field (Pa) \\
$\rho$ & mass density (kg/m$^3$) \\
$\lambda_h$ & stabilisation parameter of the discrete scheme \\
$\Delta t, \Delta h$ & time step and element size \\
\end{tabular}
\end{center}

\medskip
\noindent Throughout the paper the mass density is denoted $\varrho$;
its role in the weak form is defined in Section~2.
